import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Highly reliable ECDKART Logo widget that renders the official brand logo
/// with 100% transparent background using inlined image memory bytes.
/// This guarantees 0 404 asset loading issues on Flutter Web, Android, iOS, and Desktop.
class EcdkartLogo extends StatelessWidget {
  final double? height;
  final double? width;
  final BoxFit fit;

  const EcdkartLogo({
    super.key,
    this.height,
    this.width,
    this.fit = BoxFit.contain,
  });

  static final Uint8List _logoBytes = base64Decode(
    '',
  );

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _logoBytes,
      height: height,
      width: width,
      fit: fit,
      errorBuilder: (context, error, stackTrace) => Image.asset(
        'assets/images/image.png',
        height: height,
        width: width,
        fit: fit,
      ),
    );
  }
}
